$recent = $pdo->query('SELECT cr.id, cr.fecha_atencion, cr.motivo_consulta, cr.estado, p.nombres, p.apellidos, p.numero_documento, p.tipo_documento FROM historias_clinicas cr JOIN pacientes p ON p.id=cr.paciente_id ORDER BY cr.fecha_atencion DESC LIMIT 5')->fetchAll();
